#!/usr/bin/env python3
"""ProTrackAI v3.39 on the demo page: budget supplement / returns requests and change requests, started in ProTrack and
approved through Approval Hub (recorded by hand on the demo page), posted to the budget supplement log and the change
order and claim log, with the version movable. Usage: python3 wf_demo.py DEMO_HTML XLSX_FULL_MIN_JS > results_wf_demo.json"""
import json, os, sys, tempfile
from playwright.sync_api import sync_playwright

PAGE, SJS = os.path.abspath(sys.argv[1]), os.path.abspath(sys.argv[2])
R = []
def ck(area, name, cond, detail=''):
    R.append({'area': area, 'check': name, 'result': 'PASS' if cond else 'FAIL', 'detail': '' if cond else str(detail)[:500]})
    print(('PASS ' if cond else 'FAIL ') + area + ': ' + name + ('' if cond else '  -> ' + str(detail)[:500]), file=sys.stderr)
CHART = "window.Chart=function(){return{destroy(){},update(){},resize(){},data:{datasets:[]},options:{}}};window.Chart.register=function(){};window.Chart.defaults={font:{},plugins:{legend:{labels:{}},tooltip:{}},scale:{grid:{}},color:''};"
XL = open(SJS).read()
def route(r):
    u = r.request.url
    if u.startswith('http'):
        if 'xlsx' in u: return r.fulfill(body=XL, content_type='application/javascript')
        if 'chart' in u.lower(): return r.fulfill(body=CHART, content_type='application/javascript')
        return r.abort()
    return r.continue_()
with sync_playwright() as p:
    b = p.chromium.launch(executable_path='/opt/pw-browsers/chromium-1194/chrome-linux/chrome')
    ctx = b.new_context(viewport={'width': 1440, 'height': 900}, accept_downloads=True); ctx.route('**/*', route)
    pg = ctx.new_page(); errs = []; pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto('file://' + PAGE); pg.wait_for_timeout(900)
    J = pg.evaluate
    def login(email):
        if pg.locator('#app').is_visible(): J('signOut()'); pg.wait_for_timeout(600)
        pg.fill('#lgId', email); pg.fill('#lgPw', 'ProTrack@2026'); pg.click('#lgBtn'); pg.wait_for_selector('#app', state='visible', timeout=10000); pg.wait_for_timeout(1000)
        J("window.aiHint=()=>{};window.rasaBubble=()=>{}")
    toast = lambda: J("document.querySelector('#toast').textContent")
    def xl(dl):
        import openpyxl; p_ = os.path.join(tempfile.mkdtemp(), 'x.xlsx'); dl.value.save_as(p_); return openpyxl.load_workbook(p_)
    login('asarudeen@company.com')
    pid = 'RMX'
    pe = J(f"DB.master.users.find(u=>u.role==='plan'&&u.active!==false&&accessIds(u).includes('{pid}')).email")
    cc = J(f"DB.master.users.find(u=>isCoord(u)&&accessIds(u).includes('{pid}')).email")
    fo = J("(DB.master.users.find(u=>u.role==='foreman'&&u.active!==false)||{}).email")
    login(pe); J(f"state.wfUi=Object.assign(wfUi(),{{pid:'{pid}',open:null,tab:'list'}});go('wfr')"); pg.wait_for_timeout(500)
    nav = J("[...document.querySelectorAll('#nav .nav-item')].map(x=>x.textContent.trim()).join('|')")
    ck('Navigation', 'Budget & change requests sits in Cost Control, after Budget supplements', 'Budget supplements|Budget & change requests' in nav, nav[:300])
    v = pg.inner_text('#view')
    ck('List', 'the page says the forms are approved in Approval Hub and posted to the logs, and that the hub is not connected on the demo page', 'approved in Approval Hub' in v and 'not connected yet' in v)
    pg.click('[data-wfnew="BRF"]'); pg.wait_for_timeout(600); v = pg.inner_text('#view')
    fid = J("wfUi().open")
    ck('BRF', 'a planning engineer starts a Budget Supplement / Returns Request: BR-01, a draft, in the company layout (sections 01 to 06)', J(f"wfForm('{fid}').ref_no") == 'BR-01' and all(x in v for x in ['01. General Information', '02. Brief Description', '03. Budget Summary', '04. Impact on Project Margin', '05. Category wise Details', '06. Final Agreement', 'AP/Planning-BRF']), v[:500])
    ck('BRF', 'general information comes from the project master (name, PE number, region, contract value)', 'Riyadh Metro Line 7' in J("document.querySelector('#view').innerHTML") and J(f"wfForm('{fid}').data.impact.ocv") == 420000000)
    def line(i, desc, cat, uf, supp=None, sav=None, wbs=''):
        r = pg.locator(f'[data-wfl="{i}"]')
        r.locator('[data-wl="description"]').fill(desc); r.locator('[data-wl="category"]').select_option(cat); r.locator('[data-wl="user_field"]').select_option(uf)
        if supp: r.locator('[data-wl="supp"]').fill(str(supp))
        if sav: r.locator('[data-wl="sav"]').fill(str(sav))
        if wbs: r.locator('[data-wl="wbs_id"]').fill(wbs)
    line(0, 'Estimate overrun in salaries according to delay in TCC', 'Project Execution', 'SM', supp=120000, wbs='RMX-01-001-01')
    pg.click('[data-wfladd]'); pg.wait_for_timeout(400); line(1, 'Actual expenses overrun in 132kV power cables manpower', 'Project Execution', 'MAN.ELC', supp=47650)
    pg.click('[data-wfladd]'); pg.wait_for_timeout(400); line(2, 'Saving as per attached sheets', 'Cont-Savings', 'CONT', sav=1939967)
    pg.fill('[data-wft]', 'Salaries, cables and contingency release')
    s = pg.locator('[data-wfs]'); J("document.querySelectorAll('[data-wfs][data-k=\"C\"]')[0].value='5339111'")
    pg.click('[data-wfsave]'); pg.wait_for_timeout(500)
    f = J(f"wfForm('{fid}')")
    ck('BRF', 'the lines are saved signed as in the log: supplements negative, the saving positive', [l['amount'] for l in f['lines']] == ['-120000', '-47650', '1939967'], f['lines'])
    ck('BRF', 'contingency adds the Vice President to the approval chain', f['approvers'][-1] == 'Vice President' and 'Planning Manager' in f['approvers'])
    v = pg.inner_text('#view')
    ck('BRF', 'section 03 computes the request by user field: SM current 5,339,111, this request -120,000, revised estimate 5,459,111', '5,339,111.00' in v and '-120,000.00' in v and '5,459,111.00' in v, v[v.find('03. Budget'):v.find('03. Budget')+900])
    ck('BRF', 'section 05 puts this request by unified category', 'Project Execution' in v and '-167,650.00' in v and '1,939,967.00' in v)
    with pg.expect_download() as dl: pg.click('[data-wfxl]')
    wb = xl(dl); ws = wb.worksheets[0]; vals = [c for r in ws.iter_rows(values_only=True) for c in r if c is not None]
    ck('Excel', 'the form downloads in the company layout: title, reference, lines, budget summary, impact and the approval box', 'BUDGET SUPPLEMENT/ RETURNS REQUEST' in vals and 'AP/Planning-BRF' in vals and 'Saving as per attached sheets' in vals and 'Vice President' in vals and -120000 in vals and 'Category details' in wb.sheetnames, vals[:20])
    J(f"document.querySelector('[data-wfl=\"1\"] [data-wl=\"description\"]').value=''")
    pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    ck('Submit', 'a line without its description is refused, naming the line', 'Line 2: give the short description' in toast(), toast())
    pg.locator('[data-wfl="1"] [data-wl="description"]').fill('Actual expenses overrun in 132kV power cables manpower'); pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    f = J(f"wfForm('{fid}')")
    ck('Submit', 'submitted to Approval Hub (queued), with its totals; it is no longer changed', f['status'] == 'Submitted' and f['totals']['net'] == 1772317 and J("DB.wfOutbox.length") == 1 and pg.locator('[data-wfsave]').count() == 0, f.get('totals'))
    ck('Submit', 'the planning engineer cannot record the decision', pg.locator('[data-wfrecord]').count() == 0)
    login(cc); J(f"state.wfUi=Object.assign(wfUi(),{{pid:'{pid}',open:'{fid}'}});go('wfr')"); pg.wait_for_timeout(500)
    pg.fill('#wfRW', ''); pg.click('[data-wfrecord]'); pg.wait_for_timeout(400)
    ck('Record', 'the WF number is needed', 'WF number' in toast(), toast())
    pg.fill('#wfRW', 'WF-1001'); pg.fill('#wfRA', 'Vice President'); pg.click('[data-wfrecord]'); pg.wait_for_timeout(600)
    f = J(f"wfForm('{fid}')"); M = J("curMonth()")
    ck('Record', 'the costing coordinator records the approval by hand: approved, version of this month, posted', f['status'] == 'Approved' and f['version'] == M and f['decision_source'] == 'manual' and f['posted']['rows'] == ['BR-01/1', 'BR-01/2', 'BR-01/3'], f.get('posted'))
    rows = J(f"suppLatestAny('{pid}').rows.filter(r=>r.wf_form==='{fid}').map(r=>[r.supp_no,r.amount,r.user_field,r.version,r.wf_no,r.supp_date])")
    ck('Log', 'three rows in the budget supplement log with the WF number, the version and the approval date', len(rows) == 3 and rows[0][1] == -120000 and rows[2][2] == 'CONT' and all(r[3] == M and r[4] == 'WF-1001' for r in rows), rows)
    r = J(f"(()=>{{try{{suppActLocal({{action:'remove',project_id:'{pid}',id:suppLatestAny('{pid}').rows.find(r=>r.supp_no==='BR-01/1').id,reason:'no longer needed'}});return 'removed'}}catch(e){{return e.message}}}})()")
    ck('Log', 'a row posted from a WF is not removed on the log screen', 'posted from the approved WF WF-1001' in r, r)
    r = J(f"(()=>{{const x=suppLatestAny('{pid}').rows.find(r=>r.supp_no==='BR-01/2');try{{suppActLocal({{action:'edit',project_id:'{pid}',id:x.id,values:{{...x,amount:-1}}}});return 'changed'}}catch(e){{return e.message}}}})()")
    ck('Log', '...nor is its amount changed', 'only its version and remarks' in r, r)
    P = J("wfPrev(curMonth())")
    pg.select_option('#wfVer', P); pg.click('[data-wfver]'); pg.wait_for_timeout(400)
    ck('Version', 'moving the version needs a reason', 'reason' in toast().lower(), toast())
    pg.select_option('#wfVer', P); pg.fill('#wfVerR', 'management approved the values in the previous month'); pg.click('[data-wfver]'); pg.wait_for_timeout(500)
    ck('Version', 'the version moves to the previous month: the form and its three rows', J(f"wfForm('{fid}').version") == P and J(f"suppLatestAny('{pid}').rows.filter(r=>r.wf_form==='{fid}').every(r=>r.version==='{P}')"))
    J("state.logTab='supp';go('logs')"); pg.wait_for_timeout(600)
    ck('Log', 'the supplement log screen lists the posted rows', 'BR-01/3' in pg.inner_text('#view'))
    # a return and a resubmission
    login(pe); J(f"state.wfUi=Object.assign(wfUi(),{{pid:'{pid}',open:null}});go('wfr')"); pg.wait_for_timeout(400); pg.click('[data-wfnew="BRF"]'); pg.wait_for_timeout(500); f2 = J("wfUi().open")
    line(0, 'Management reserve for prolongation', 'Mgmt Res-Proj Exe', 'MGT.RES', supp=300000); pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    ck('BRF', 'the management reserve adds the Executive Vice President', J(f"wfForm('{f2}').approvers.slice(-1)[0]") == 'Executive Vice President' and J(f"wfForm('{f2}').ref_no") == 'BR-02')
    login(cc); J(f"state.wfUi=Object.assign(wfUi(),{{open:'{f2}'}});go('wfr')"); pg.wait_for_timeout(400)
    pg.select_option('#wfRD', 'returned'); pg.fill('#wfRW', 'WF-2002'); pg.click('[data-wfrecord]'); pg.wait_for_timeout(400)
    ck('Record', 'a return needs its reason', 'reason' in toast().lower(), toast())
    pg.fill('#wfRC', 'attach the prolongation sheet'); pg.click('[data-wfrecord]'); pg.wait_for_timeout(400)
    login(pe); J(f"state.wfUi=Object.assign(wfUi(),{{open:'{f2}'}});go('wfr')"); pg.wait_for_timeout(400); v = pg.inner_text('#view')
    ck('Return', 'the preparer sees it returned with the reason, and can correct it', 'Returned from Approval Hub (WF WF-2002): attach the prolongation sheet' in v and pg.locator('[data-wfsubmit]').count() == 1, v[:600])
    pg.locator('[data-wfl="0"] [data-wl="supp"]').fill('250000'); pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    ck('Return', 'submitted again, keeping the WF number', J(f"(f=>f.status+'/'+f.wf_no+'/'+f.lines[0].amount)(wfForm('{f2}'))") == 'Submitted/WF-2002/-250000')
    # a change request
    J("wfUi().open=null;render()"); pg.wait_for_timeout(300); pg.click('[data-wfnew="CRF"]'); pg.wait_for_timeout(500); c1 = J("wfUi().open")
    pg.fill('[data-wfd="description"]', 'Additional 132kV cable route'); pg.fill('[data-wfd="client_ref"]', 'SEC/VO/14'); pg.fill('[data-wfd="price_submitted"]', '600000'); pg.fill('[data-wfd="price_client"]', '500000')
    pg.fill('[data-wfd="cost_current"]', '400000'); pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    ck('CRF', 'a client approved price without the client approval is refused', 'client approved price needs' in toast(), toast())
    pg.select_option('[data-wfd="client_status"]', 'Approved'); pg.click('[data-wfsubmit]'); pg.wait_for_timeout(500)
    ck('CRF', 'CR-01 submitted', J(f"(f=>f.ref_no+'/'+f.status)(wfForm('{c1}'))") == 'CR-01/Submitted')
    login(cc); J(f"state.wfUi=Object.assign(wfUi(),{{open:'{c1}'}});go('wfr')"); pg.wait_for_timeout(400); pg.fill('#wfRW', 'WF-4004'); pg.click('[data-wfrecord]'); pg.wait_for_timeout(500)
    row = J(f"(r=>r&&[r.kind,r.est_price,r.client_price,r.est_cost,r.client_status,r.wf_no])(voLatest('{pid}','9999-12').rows.find(r=>r.ref_no==='CR-01'))")
    ck('CRF', 'approved: added to the change order and claim log with its prices, cost, client status and WF', row == ['VO', 600000, 500000, 400000, 'Approved', 'WF-4004'], row)
    J("wfUi().open=null;render()"); pg.wait_for_timeout(300); v = pg.inner_text('#view')
    ck('List', 'the list shows the forms with their status, WF and version', all(x in v for x in ['BR-01', 'BR-02', 'CR-01', 'WF-1001', 'Approved', 'Submitted']))
    J("wfUi().tab='hub';render()"); pg.wait_for_timeout(300)
    ck('Hub', 'the Approval Hub tab explains the link (wf_hub_next, wf_hub_update) and the manual recording', 'wf_hub_next' in pg.inner_text('#view') and 'records each decision' in pg.inner_text('#view'))
    login(fo)
    ck('Rights', 'a foreman does not see the page', 'Budget & change requests' not in pg.inner_text('#nav'))
    ck('Page', 'no script errors', not errs, errs[:3])
    b.close()
print(json.dumps({'suite': 'wf_demo', 'passed': sum(r['result'] == 'PASS' for r in R), 'total': len(R), 'checks': R}, indent=1))
